update lerninhalte set daten = jsonb_set(daten, '{pflegeplanung}', (daten->'pflegeplanung') || '[{"problem": "Aktivitätsintoleranz infolge Atemnot, erkennbar an Dyspnoe bei der Körperpflege und Pausen nach wenigen Schritten", "ressourcen": ["motiviert", "kennt die Lippenbremse", "nutzt einen Rollator"], "ziel": "führt die Körperpflege am Waschbecken innerhalb von 5 Tagen mit höchstens 2 Pausen selbstständig durch", "massnahmen": ["Tätigkeiten mit Pausen planen und über den Tag verteilen", "Lippenbremse und atemerleichternde Positionen (z. B. Kutschersitz) anleiten", "Sauerstoff bei Belastung nach Anordnung", "Mobilisation schrittweise steigern", "Hilfsmittel einsetzen (Duschhocker, Rollator)", "SpO₂ und Atemfrequenz bei Belastung kontrollieren"], "evaluation": "täglich Belastbarkeit und Atemnot (z. B. Borg-Skala) dokumentieren"}]'::jsonb), stand = current_date where slug = 'pflegeplanung-copd' and jsonb_array_length(daten->'pflegeplanung') = 1;
update lerninhalte set daten = jsonb_set(daten, '{pflegeplanung}', (daten->'pflegeplanung') || '[{"problem": "Ineffektive Atemwegsclearance infolge zähen Sekrets und Schwäche, erkennbar an Rasselgeräuschen und kraftlosem Husten", "ressourcen": ["kann sitzen", "versteht Anleitung"], "ziel": "hustet Sekret innerhalb von 72 Stunden selbstständig ab, Atemgeräusch zunehmend frei", "massnahmen": ["Oberkörper hochlagern und früh mobilisieren", "Atemübungen und Hustentechnik (Huffing) anleiten", "ausreichende Flüssigkeitszufuhr nach Anordnung", "Inhalation nach Anordnung", "Sekret nach Menge, Farbe und Konsistenz beurteilen", "bei Bedarf absaugen"], "evaluation": "täglich Sekret, Atemgeräusch, Atemfrequenz und SpO₂"}]'::jsonb), stand = current_date where slug = 'pflegeplanung-pneumonie' and jsonb_array_length(daten->'pflegeplanung') = 1;
update lerninhalte set daten = jsonb_set(daten, '{pflegeplanung}', (daten->'pflegeplanung') || '[{"problem": "Risiko einer Mangelernährung und Austrocknung infolge vergessener Mahlzeiten und fehlenden Durstgefühls", "ressourcen": ["isst gern Fingerfood", "Tochter besucht täglich"], "ziel": "trinkt täglich die festgelegte Menge (z. B. 1,5 l, sofern keine Beschränkung) und hält das Gewicht über 4 Wochen stabil", "massnahmen": ["Getränke sichtbar und regelmäßig anbieten, Trinkprotokoll führen", "Fingerfood und Lieblingsspeisen anbieten", "ruhige Essenssituation, gemeinsam essen", "Mundzustand und Prothese prüfen", "Ernährungsscreening, wöchentlich wiegen", "Tochter einbeziehen"], "evaluation": "täglich Trinkprotokoll, wöchentlich Gewicht"}]'::jsonb), stand = current_date where slug = 'pflegeplanung-demenz' and jsonb_array_length(daten->'pflegeplanung') = 1;
update lerninhalte set daten = jsonb_set(daten, '{pflegeplanung}', (daten->'pflegeplanung') || '[{"problem": "Risiko eines Wirkungsverlusts der Parkinson-Medikamente infolge unregelmäßiger Einnahme", "ressourcen": ["kennt seinen Medikamentenplan", "Ehefrau unterstützt"], "ziel": "Medikamente werden während des Aufenthalts zu 100 % zeitgenau eingenommen, Wirkschwankungen sind dokumentiert", "massnahmen": ["Einnahmezeiten exakt nach Plan einhalten, auch nachts und vor Untersuchungen", "L-Dopa nach Anordnung mit Abstand zu eiweißreichen Mahlzeiten", "On- und Off-Phasen beobachten und dokumentieren", "Schluckfähigkeit beobachten, bei Schluckstörung Arzt informieren", "Patient und Angehörige schulen"], "evaluation": "täglich Einnahmeprotokoll und Beweglichkeit im Tagesverlauf"}]'::jsonb), stand = current_date where slug = 'pflegeplanung-parkinson' and jsonb_array_length(daten->'pflegeplanung') = 1;
update lerninhalte set daten = jsonb_set(daten, '{pflegeplanung}', (daten->'pflegeplanung') || '[{"problem": "Akute Schmerzen infolge des Operationstraumas, erkennbar an NRS 6 und Schonhaltung bei der Mobilisation", "ressourcen": ["kann Schmerzen klar benennen", "möchte schnell mobil werden"], "ziel": "Schmerz in Ruhe NRS ≤ 3 und bei Mobilisation NRS ≤ 4 innerhalb von 24 Stunden", "massnahmen": ["Schmerz regelmäßig mit NRS erfassen, auch vor und nach der Mobilisation", "Analgetika nach Anordnung rechtzeitig vor der Mobilisation geben", "Kühlung nach Anordnung", "schmerzarme Lagerung", "Wirkung und Nebenwirkungen dokumentieren", "Ablauf der Mobilisation vorher erklären"], "evaluation": "mehrmals täglich NRS in Ruhe und bei Belastung"}]'::jsonb), stand = current_date where slug = 'pflegeplanung-hueft-tep' and jsonb_array_length(daten->'pflegeplanung') = 1;
update lerninhalte set daten = jsonb_set(daten, '{pflegeplanung}', (daten->'pflegeplanung') || '[{"problem": "Risiko eines Delirs infolge hohen Alters, Operation, Schmerzen und ungewohnter Umgebung", "ressourcen": ["Angehörige kommen täglich", "trägt Brille und Hörgerät"], "ziel": "während des Aufenthalts kein Delir (Screening unauffällig)", "massnahmen": ["täglich Delir-Screening (z. B. 4AT)", "Orientierungshilfen (Uhr, Kalender, Namen nennen)", "Brille und Hörgerät einsetzen", "Schmerztherapie nach Anordnung", "auf Trinkmenge, Ausscheidung und Schlaf achten", "frühe Mobilisation", "Angehörige einbeziehen", "Veränderungen sofort melden"], "evaluation": "täglich Screening-Ergebnis und Verhalten im Tagesverlauf"}]'::jsonb), stand = current_date where slug = 'pflegeplanung-schenkelhalsfraktur' and jsonb_array_length(daten->'pflegeplanung') = 1;
update lerninhalte set daten = jsonb_set(daten, '{pflegeplanung}', (daten->'pflegeplanung') || '[{"problem": "Angst des Kindes und der Eltern infolge Atemnot und Krankenhausaufenthalt, erkennbar an Weinen, Anklammern und Unruhe", "ressourcen": ["Eltern sind anwesend", "Lieblingskuscheltier ist dabei"], "ziel": "Kind wirkt innerhalb von 24 Stunden ruhiger; Eltern können bis zur Entlassung Inhalationstechnik und Notfallplan erklären", "massnahmen": ["Eltern einbeziehen (Rooming-in)", "ruhige Umgebung schaffen", "Maßnahmen kindgerecht erklären", "Inhalation mit Spacer gemeinsam üben", "schriftlichen Asthma-Notfallplan besprechen", "Auslöser und Vermeidung erklären"], "evaluation": "täglich Verhalten des Kindes; vor Entlassung erklären die Eltern Inhalation und Notfallplan selbst (Teach-back)"}]'::jsonb), stand = current_date where slug = 'pflegeplanung-asthma-kind' and jsonb_array_length(daten->'pflegeplanung') = 1;
